class Solution {
    private int[] distances(int[] edges,int start){
        int[] distance=new int[edges.length];
        Arrays.fill(distance,-1);
        for(int steps=0;start!=-1&&distance[start]==-1;steps++){
            distance[start]=steps;
            start=edges[start];
        }
        return distance;
    }
    public int closestMeetingNode(int[] edges,int node1,int node2){
        int[] first=distances(edges,node1),second=distances(edges,node2);
        int answer=-1,best=Integer.MAX_VALUE;
        for(int i=0;i<edges.length;i++)if(first[i]>=0&&second[i]>=0&&Math.max(first[i],second[i])<best){
            best=Math.max(first[i],second[i]);
            answer=i;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun distances(edges:IntArray,startValue:Int):IntArray{
        val distance=IntArray(edges.size){
            -1
        };
        var node=startValue;
        var steps=0;
        while(node!=-1&&distance[node]==-1){
            distance[node]=steps++;
            node=edges[node]
        };
        return distance
    };
    fun closestMeetingNode(edges:IntArray,node1:Int,node2:Int):Int{
        val first=distances(edges,node1);
        val second=distances(edges,node2);
        var answer=-1;
        var best=Int.MAX_VALUE;
        for(i in edges.indices)if(first[i]>=0&&second[i]>=0&&maxOf(first[i],second[i])<best){
            best=maxOf(first[i],second[i]);
            answer=i
        };
        return answer
    }
}

